const fs = require("fs");
const path = require("path");
const childProcess = require("child_process");

const PSOLA = require("../../util/psola.js");
const env = require("../../util/env-util.js");
const TempFolder = require('../../util/temp-folder.js');
const FFmpegUtil = require("../../util/ffmpeg-util.js");
const downloadAttachments = require('../../util/download-attachments.js');

class Command {
    constructor() {
        this.name = "vocode";
        this.description = "Transfer pitch from a sample to another";
        this.descriptionLong = "Transfer pitch from a sample to another"
            + "\n" + "-" + " " + "The first audio file is the audio clip to use as the base."
            + "\n" + "-" + " " + "The second audio file is used as the modulator; pitch is extracted from this file.";
        this.attributes = {
            unlisted: false,
            lockedToCommands: true,
            permission: 0,
        };

        this.alias = ["transferpitch", "pitchtransfer"];
    }

    getAttachments(message, args, util) {
        // check attachements
        const attachment1 = message.attachments.first();
        const attachment2 = message.attachments.last();
        if (!attachment1) throw new Error("Add an audio to use as base");
        if (!attachment2) throw new Error("Add an audio to grab pitch from");
        const endingTypeRaw1 = util.getAttachmentType(attachment1);
        const endingTypeRaw2 = util.getAttachmentType(attachment2);
        if (!FFmpegUtil.isCompatibleAudio(endingTypeRaw1))
            throw new Error('Please use a valid audio format. (video 1)');
        if (!FFmpegUtil.isCompatibleAudio(endingTypeRaw2))
            throw new Error('Please use a valid audio format. (video 2)');
        // check atachemtn size
        if (attachment1.size > 15 * 1e+6) throw new Error("Files must be below 15 MB.");
        if (attachment2.size > 15 * 1e+6) throw new Error("Files must be below 15 MB.");
        return [attachment1, attachment2];
    }
    async handle(message, args, util) {
        const [attachment1, attachment2] = this.getAttachments(message, args, util);

        // actually start doing stuff
        const startTime = Date.now();
        const jobName = TempFolder.makeTempName("vocode");
        const temporaryFolder = new TempFolder(jobName);
        await temporaryFolder.createAndDestroy(async (tempDir) => {
            // download
            const replyMessage = await message.reply("Downloading contents...");
            const [rawPath1, rawPath2] = await downloadAttachments([attachment1, attachment2], (i) => `input${i}.bin`, tempDir);
            // convert to safe types
            await replyMessage.edit("Converting contents...");
            const path1 = path.join(tempDir, "inputsafe1.ogg");
            const path2 = path.join(tempDir, "inputsafe2.ogg");
            await FFmpegUtil.commands.convertToSafeOgg(rawPath1, path1);
            await FFmpegUtil.commands.convertToSafeOgg(rawPath2, path2);
            // check length
            const length1 = await FFmpegUtil.probe.length(path1);
            const length2 = await FFmpegUtil.probe.length(path2);
            if (length1 > 5 * 60) return replyMessage.edit("Files must be within 5 minutes long OR you can buy me 64 gigabytes of ram 🎉");
            if (length2 > 5 * 60) return replyMessage.edit("Files must be within 5 minutes long OR you can buy me 64 gigabytes of ram 🎉");

            // do the thing
            const outputPathWav = path.join(tempDir, "output_vocode.wav");
            await replyMessage.edit(`Generating vocode output...`
                + `\n` + `(SOURCE: ${attachment1.name}, MODIFIER: ${attachment2.name})`);
            await PSOLA.transferPitch(path1, path2, outputPathWav);

            // convret to ogg
            await replyMessage.edit(`making ogg because Hfat file`);
            const outputPathCorrected = path.join(tempDir, "vocode_transfer.ogg");
            await FFmpegUtil.commands.convertToSafeOgg(outputPathWav, outputPathCorrected);

            await replyMessage.edit({
                content: "Completed in " + ((Date.now() - startTime) / 1000) + " seconds"
                    + "\n" + `-# Generated by <@${message.author.id}>`,
                files: [outputPathCorrected]
            });
        });
    }
    async invoke(message, args, util) {
        await this.handle(message, args, util);
    }
}

// needs to do new Command() in index.js because typing static every time STINKS!
module.exports = Command;